// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/challenges/{challenge_id}", wrapper.GetChallenge)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/challenges/{challenge_id}/exercises", wrapper.CreateExercise)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/content-nodes", wrapper.CreateContentNode)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/content-nodes/{content_node_id}", wrapper.GetContentNode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/content-nodes/{content_node_id}/challenges", wrapper.CreateChallenge)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/content-nodes/{content_node_id}/expanded-content", wrapper.ListExpandedContent)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/content-nodes/{content_node_id}/expanded-content", wrapper.CreateExpandedContent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/exercises/{exercise_id}", wrapper.GetExercise)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/expanded-content/{expanded_content_id}", wrapper.GetExpandedContent)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/learning-paths", wrapper.CreateLearningPath)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/learning-paths/{learning_path_id}", wrapper.GetLearningPath)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/students/me/path", wrapper.GetMyPath)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/students/{student_id}/path-assignments", wrapper.AssignLearningPath)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/users", wrapper.RegisterUser)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/users/me", wrapper.GetMyProfile)
	})

	return r
}

