// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Get a challenge by ID
	// (GET /challenges/{challenge_id})
	GetChallenge(ctx context.Context, request GetChallengeRequestObject) (GetChallengeResponseObject, error)
	// Create an exercise within a challenge
	// (POST /challenges/{challenge_id}/exercises)
	CreateExercise(ctx context.Context, request CreateExerciseRequestObject) (CreateExerciseResponseObject, error)
	// Create a content node
	// (POST /content-nodes)
	CreateContentNode(ctx context.Context, request CreateContentNodeRequestObject) (CreateContentNodeResponseObject, error)
	// Get a content node by ID
	// (GET /content-nodes/{content_node_id})
	GetContentNode(ctx context.Context, request GetContentNodeRequestObject) (GetContentNodeResponseObject, error)
	// Create a challenge for a content node
	// (POST /content-nodes/{content_node_id}/challenges)
	CreateChallenge(ctx context.Context, request CreateChallengeRequestObject) (CreateChallengeResponseObject, error)
	// List all expanded content items for a content node
	// (GET /content-nodes/{content_node_id}/expanded-content)
	ListExpandedContent(ctx context.Context, request ListExpandedContentRequestObject) (ListExpandedContentResponseObject, error)
	// Add an expanded content item to a content node
	// (POST /content-nodes/{content_node_id}/expanded-content)
	CreateExpandedContent(ctx context.Context, request CreateExpandedContentRequestObject) (CreateExpandedContentResponseObject, error)
	// Get an exercise by ID
	// (GET /exercises/{exercise_id})
	GetExercise(ctx context.Context, request GetExerciseRequestObject) (GetExerciseResponseObject, error)
	// Get an expanded content item by ID
	// (GET /expanded-content/{expanded_content_id})
	GetExpandedContent(ctx context.Context, request GetExpandedContentRequestObject) (GetExpandedContentResponseObject, error)
	// Create a learning path
	// (POST /learning-paths)
	CreateLearningPath(ctx context.Context, request CreateLearningPathRequestObject) (CreateLearningPathResponseObject, error)
	// Get a learning path by ID
	// (GET /learning-paths/{learning_path_id})
	GetLearningPath(ctx context.Context, request GetLearningPathRequestObject) (GetLearningPathResponseObject, error)
	// Get the authenticated student's current learning path and progress
	// (GET /students/me/path)
	GetMyPath(ctx context.Context, request GetMyPathRequestObject) (GetMyPathResponseObject, error)
	// Assign a learning path to a student
	// (POST /students/{student_id}/path-assignments)
	AssignLearningPath(ctx context.Context, request AssignLearningPathRequestObject) (AssignLearningPathResponseObject, error)
	// Register an authenticated user
	// (POST /users)
	RegisterUser(ctx context.Context, request RegisterUserRequestObject) (RegisterUserResponseObject, error)
	// Get the authenticated user's profile
	// (GET /users/me)
	GetMyProfile(ctx context.Context, request GetMyProfileRequestObject) (GetMyProfileResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

